namespace gui_forms {

// TrackBar's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/track_bar.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Distance in value units between tick marks; positive and finite, else std::invalid_argument.
template <typename Declaring>
struct TrackBarTickFrequencyCapability {
    PropertyCell<double, TrackBarTickFrequencyCapability<Declaring>> tick_frequency{10.0};

    static void assign(TrackBarTickFrequencyCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.tick_frequency), incoming);
        if (!capability.tick_frequency.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.tick_frequency));
    }
};

// Whether the tick marks draw.
template <typename Declaring>
struct TrackBarShowTicksCapability {
    PropertyCell<bool, TrackBarShowTicksCapability<Declaring>> show_ticks{true};

    static void assign(TrackBarShowTicksCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.show_ticks), incoming);
        if (!capability.show_ticks.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.show_ticks));
    }
};

// How the rail and thumb draw: classic ticks, a filled rail or a compact rail.
template <typename Declaring>
struct TrackBarVisualStyleChoiceCapability {
    PropertyCell<TrackBarVisualStyle, TrackBarVisualStyleChoiceCapability<Declaring>> visual_style{TrackBarVisualStyle::classic};

    static void assign(TrackBarVisualStyleChoiceCapability& capability, TrackBarVisualStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.visual_style), incoming);
        if (!capability.visual_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.visual_style));
    }
};

// The thumb's side in pixels; 0 (the default) takes the visual style's (14 classic, 12 filled, 8 compact). Finite and between 0 and 64, else std::invalid_argument.
template <typename Declaring>
struct TrackBarThumbExtentCapability {
    PropertyCell<double, TrackBarThumbExtentCapability<Declaring>> thumb_extent{0.0};

    static void assign(TrackBarThumbExtentCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.thumb_extent), incoming);
        if (!capability.thumb_extent.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.thumb_extent));
    }
};

// TrackBarVisualStyle as a property value; defined beside TrackBar's table.
template <>
struct PropertyValueTraits<TrackBarVisualStyle> {
    static PropertyType type();
    static BindingValue to_binding(TrackBarVisualStyle value);
    static TrackBarVisualStyle from_binding(const BindingValue& value);
};

// Every TrackBar capability, in the order the declaring class takes them.
template <typename Declaring>
struct TrackBarCapabilities : public TrackBarTickFrequencyCapability<Declaring>,
                              public TrackBarShowTicksCapability<Declaring>,
                              public TrackBarVisualStyleChoiceCapability<Declaring>,
                              public TrackBarThumbExtentCapability<Declaring> {};

} // namespace gui_forms
